def rpn_eval(tokens):
    def op(symbol, a, b):
        return {
            '+': lambda a, b: a + b,
            '-': lambda a, b: a - b,
            '*': lambda a, b: a * b,
            '/': lambda a, b: a / b
        }[symbol](a, b)

    stack = []

    for token in tokens:
        if isinstance(token, float):
            stack.append(token)
        else:
            a = stack.pop()
            b = stack.pop()
            stack.append(
                op(token, a, b)
            )

    return stack.pop()

print(rpn_eval([3.0, 5.0, '+', 2.0, '/']))
print(rpn_eval([2.0, 2.0, '+']))
print(rpn_eval([7.0, 4.0, '+', 3.0, '-']))

